settings.custom_css:
/* =========================================================
   GREEN SKY TRAVELS — SOCIABLEKIT GOOGLE REVIEWS
   ========================================================= */

/* Main widget */
.sk-ww-google-reviews {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  font-family: inherit;
}

/* Review cards */
.sk-ww-google-reviews .sk-review {
  border-radius: 18px !important;
  border: 1px solid #e8ecef !important;
  background: #ffffff !important;
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.06) !important;
  padding: 24px !important;
  transition: all 0.3s ease !important;
}

/* Card hover */
.sk-ww-google-reviews .sk-review:hover {
  transform: translateY(-4px);
  box-shadow: 0 14px 35px rgba(0, 0, 0, 0.10) !important;
}

/* Reviewer name */
.sk-ww-google-reviews .sk-reviewer-name {
  color: #073b20 !important;
  font-weight: 700 !important;
  font-size: 16px !important;
}

/* Review text */
.sk-ww-google-reviews .sk-review-text {
  color: #4b5563 !important;
  font-size: 15px !important;
  line-height: 1.7 !important;
}

/* Google stars */
.sk-ww-google-reviews .sk-stars {
  color: #f5b301 !important;
}

/* Date */
.sk-ww-google-reviews .sk-review-date {
  color: #8a9299 !important;
  font-size: 13px !important;
}

/* Buttons */
.sk-ww-google-reviews button {
  border-radius: 999px !important;
  transition: all 0.25s ease !important;
}

/* Navigation buttons */
.sk-ww-google-reviews .sk-navigation button {
  border: 1px solid #dce5df !important;
  background: #ffffff !important;
  color: #073b20 !important;
}

.sk-ww-google-reviews .sk-navigation button:hover {
  background: #073b20 !important;
  color: #ffffff !important;
}

/* Links */
.sk-ww-google-reviews a {
  color: #073b20 !important;
}

/* Load more */
.sk-ww-google-reviews .sk-load-more {
  background: #073b20 !important;
  color: #ffffff !important;
  border-radius: 999px !important;
  padding: 12px 26px !important;
  font-weight: 600 !important;
  border: none !important;
}

.sk-ww-google-reviews .sk-load-more:hover {
  background: #0a5a30 !important;
  transform: translateY(-2px);
}

/* Mobile */
@media (max-width: 768px) {
  .sk-ww-google-reviews {
    padding: 0 10px;
  }

  .sk-ww-google-reviews .sk-review {
    padding: 20px !important;
    border-radius: 15px !important;
  }

  .sk-ww-google-reviews .sk-review-text {
    font-size: 14px !important;
  }
}
